const raw = $input.item.json.text.replace(/```json|```/g,'').trim();
const scores = JSON.parse(raw);
const high = scores.filter(c => c.risk_level === 'high');
const medium = scores.filter(c => c.risk_level === 'medium');
return [{ json: { all_scores: scores, high_risk: high, medium_risk: medium, high_count: high.length, total: scores.length } }];

